namespace Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class PlatformIdentityRolesVO
{
    public static function from(PlatformIdentityRolesVO|PlatformIdentityRolesListRef| array |null $value): PlatformIdentityRolesVO
    {
        if ($value instanceof PlatformIdentityRolesVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof PlatformIdentityRolesVO);
            return $candidate;
        }
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?PlatformIdentityRolesVO
    {
        if ($value instanceof PlatformIdentityRolesVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_array($value)) {
            return new PlatformIdentityRolesVO(PlatformIdentityRolesListRef::fromArray($value));
        } elseif (!$value) {
            return new PlatformIdentityRolesVO($value);
        } elseif (is_a($value, PlatformIdentityRolesListRef::class)) {
            return new PlatformIdentityRolesVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['roles'], [$value], ['PlatformIdentityRolesListRef']));
            return null;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?PlatformIdentityRolesListRef $roles
    ) {
    }
    public function value(): ?PlatformIdentityRolesListRef
    {
        $value = $this->roles;
        if ($value) {
            $value->rewind();
        }
        return $value;
    }
    public function find(string $uid): ?PlatformIdentityRolesItem
    {
        foreach ($this->roles as $item) {
            if ($item->uid() == $uid) {
                return $item;
            }
        }
        return null;
    }
    public function getWithDefaults(PlatformIdentityRolesVO $defs): ?PlatformIdentityRolesVO
    {
        $values = [];
        $originals = $defs->value();
        foreach ($this->roles as $item) {
            $prev = null;
            foreach ($originals as $original) {
                if ($item->uid() == $original->uid()) {
                    $prev = $original;
                    break;
                }
            }
            $values[] = $prev ? $item->getOrDefault($prev) : $item;
        }
        return PlatformIdentityRolesVO::from(PlatformIdentityRolesListRef::fromArray($values));
    }
}
